     "No trabalho, você tende a ser a pessoa que pergunta “qual é o objetivo?” antes de qualquer outra coisa e, assim que a resposta aparece, já começa a se mexer. Problema parado incomoda você mais do que problema difícil. Quando uma reunião gira em círculos, é comum que seja sua voz que diz “então vamos fazer assim” e coloca um nome e uma data ao lado da tarefa. Você costuma render mais quando existe uma meta clara, um obstáculo real e liberdade para escolher o caminho.",
