     "primeira_reacao": "Quando a pressão começa, você tende a acelerar e assumir o controle. Fala mais curto, decide sem consultar, distribui tarefas em tom de ordem e corta conversas que parecem atrasar. No curto prazo, isso costuma resolver. O efeito colateral é que as pessoas se fecham e passam a apenas obedecer, justamente quando você mais precisaria de ideias e alertas delas.",
     "se_continua": "Se a pressão dura semanas, a tendência é concentrar ainda mais: puxar tarefas para si, perder a paciência com quem pergunta e endurecer com quem erra. Como os outros fatores estão discretos no seu perfil, há pouco amortecedor. Quando nem assim o resultado vem, é comum que você se desligue do problema e busque outra frente, deixando a anterior sem fechamento.",
     "como_volta": "Você tende a voltar ao equilíbrio quando recupera alguma sensação de controle: uma vitória pequena e concreta, uma decisão que dependa só de você, um problema resolvido. Atividade física, um tempo só seu para reorganizar as prioridades e uma conversa franca com alguém que você respeita costumam ajudar. Admitir que precisa de ajuda costuma ser difícil, e muitas vezes é o passo que mais encurta a crise.",
