      "texto": "Você tende a preferir uma liderança que seja competente, coerente e previsível. Respeita quem domina o assunto e desconfia de quem decide por intuição sem explicar. Gosta de receber objetivos claros e autonomia no método, sem acompanhamento hora a hora. Feedback é bem recebido quando é específico e baseado em fatos; feedback vago ou emocional tende a gerar mais dúvida do que orientação. Também é comum que você valorize um líder que te proteja de interrupções e que defenda o tempo necessário para fazer bem feito diante de pressões externas.",
