      "texto": "Com pessoas de Dominância alta, o desafio costuma ser de ritmo. Elas querem a resposta agora e a versão curta; você quer apresentar o raciocínio completo e a entrega bem acabada. Podem achar que você demora ou detalha demais, e você pode achá-las impacientes e pouco cuidadosas. Quando você leva a conclusão primeiro e os dados no bolso, a relação tende a melhorar muito e elas passam a valorizar sua precisão.",
