      "texto": "Você costuma ter uma relação disciplinada com o tempo. Planeja com antecedência, cumpre prazos e não gosta de deixar para a última hora. Prefere trabalhar em blocos longos e sem interrupção. Seu ponto forte é a regularidade: entregas no prazo, mês após mês. O ponto de atenção é a dificuldade de abrir mão do plano quando surge algo mais importante. Você pode insistir em terminar o que estava previsto enquanto a prioridade real mudou. Também é comum assumir mais do que deveria, porque confia que vai dar conta, e muitas vezes dá, à custa de horas extras.",
