      "texto": "Com pessoas de Influência alta, a relação pode ser complementar ou desgastante. Elas trazem energia, ideias e contatos; você traz organização e cuidado com os detalhes. O atrito costuma aparecer quando o entusiasmo delas ignora prazos e procedimentos, e você fica com a parte de arrumar. Elas podem achar seu jeito formal demais; você pode achá-las dispersas. A dupla funciona quando você aproveita a capacidade delas de engajar pessoas e oferece a estrutura que transforma a ideia em entrega.",
