      "texto": "Com pessoas de Influência alta, a diferença tende a ser marcante. Elas improvisam, falam muito e decidem pela relação; você planeja, vai ao ponto e decide pelo dado. É comum você as achar pouco sérias e elas acharem seu jeito duro. Mas elas têm algo que falta ao seu estilo: a capacidade de engajar pessoas. Quando você estrutura e elas mobilizam, a mudança acontece com adesão.",
