      "texto": "Com pessoas de Estabilidade alta, a relação tende a ser produtiva no trabalho e frágil no tom. Elas valorizam a sua organização e cumprem o que você estrutura, mas podem se magoar com a sua franqueza sem dizer nada. O risco é você confundir o silêncio delas com concordância e só descobrir o desgaste quando ele já virou distância.",
